initJs:
function(container, apiUrl, tables) {
  let autoRefreshInterval = null;
  let currentLogId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#log-table-body");
    tbody.innerHTML = rows.map(row => {
      const statusClass = getStatusClass(row.処理ステータス || '');
      const startTime = formatDateTime(row.収集開始日時);
      const processingTime = row.処理時間秒 ? `${row.処理時間秒}秒` : '-';
      const qualityScore = row.データ品質スコア || '-';

      return `
        <tr data-id="${row.id}">
          <td>${startTime}</td>
          <td>${row.データ種別 || '-'}</td>
          <td>${row.データソース || '-'}</td>
          <td>${row.店舗ID || '-'}</td>
          <td><span class="status-badge ${statusClass}">${row.処理ステータス || '-'}</span></td>
          <td>${row.収集件数 || 0}</td>
          <td>${row.エラー件数 || 0}</td>
          <td>${processingTime}</td>
          <td>${qualityScore}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細</button>
            ${row.処理ステータス === '失敗' ? `<button class="action-btn secondary retry-btn" data-id="${row.id}">再実行</button>` : ''}
          </td>
        </tr>
      `;
    }).join("");

    updateSummary(rows);
  }

  // ステータスクラス取得
  function getStatusClass(status) {
    switch(status) {
      case '成功': return 'status-success';
      case '失敗': return 'status-error';
      case '実行中': return 'status-running';
      case '警告': return 'status-warning';
      default: return '';
    }
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // サマリー更新
  function updateSummary(rows) {
    const totalCount = rows.length;
    const successCount = rows.filter(r => r.処理ステータス === '成功').length;
    const errorCount = rows.filter(r => r.処理ステータス === '失敗').length;
    const lastExecution = rows.length > 0 ? 
      formatDateTime(Math.max(...rows.map(r => new Date(r.収集開始日時 || 0)))) : '-';

    container.querySelector("#total-count").textContent = totalCount;
    container.querySelector("#success-count").textContent = successCount;
    container.querySelector("#error-count").textContent = errorCount;
    container.querySelector("#last-execution").textContent = lastExecution;

    // エラーインジケーター表示制御
    const errorIndicator = container.querySelector("#error-indicator");
    if (errorCount > 0) {
      errorIndicator.classList.remove('hidden');
    } else {
      errorIndicator.classList.add('hidden');
    }
  }

  // 初期データ描画
  renderRows(tables[13].records || []);

  // 検索・絞り込み
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dataSource = container.querySelector("#filter-data-source").value;
    const logLevel = container.querySelector("#filter-log-level").value;
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を設定してください");
      return;
    }

    try {
      const rows = await window.aivicApi.list(13);
      if (!rows) return;

      const filtered = rows.filter(row => {
        if (dataSource && row.データソース !== dataSource) return false;
        if (logLevel && row.処理ステータス !== logLevel) return false;
        if (startDate && new Date(row.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(row.収集開始日時) > new Date(endDate)) return false;
        return true;
      });

      renderRows(filtered);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // ログエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(13);
      if (!rows) {
        alert("ログエクスポートに失敗しました");
        return;
      }

      const headers = ['収集日時', 'データ種別', 'データソース', '店舗ID', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア'];
      const csvContent = [
        headers.join(','),
        ...rows.map(row => [
          formatDateTime(row.収集開始日時),
          row.データ種別 || '',
          row.データソース || '',
          row.店舗ID || '',
          row.処理ステータス || '',
          row.収集件数 || 0,
          row.エラー件数 || 0,
          row.処理時間秒 || 0,
          row.データ品質スコア || 0
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `data_collection_logs_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    } catch (error) {
      alert("ログエクスポートに失敗しました");
      console.error('エクスポートエラー:', error);
    }
  });

  // エラーログ一括再実行
  container.querySelector("#btn-retry-errors").addEventListener("click", async () => {
    if (!confirm("エラーログを一括で再実行しますか？")) return;

    try {
      const rows = await window.aivicApi.list(13);
      if (!rows) return;

      const errorLogs = rows.filter(r => r.処理ステータス === '失敗');
      if (errorLogs.length === 0) {
        alert("再実行対象のエラーログがありません");
        return;
      }

      for (const log of errorLogs) {
        await window.aivicApi.update(13, log.id, {
          処理ステータス: '実行中',
          再実行フラグ: true,
          更新日時: new Date().toISOString()
        });
      }

      alert(`${errorLogs.length}件のエラーログの再実行を開始しました`);

      // 再描画
      const updatedRows = await window.aivicApi.list(13);
      if (updatedRows) renderRows(updatedRows);
    } catch (error) {
      alert("エラーログ再実行が失敗しました");
      console.error('再実行エラー:', error);
    }
  });

  // 自動更新トグル
  container.querySelector("#btn-auto-refresh-toggle").addEventListener("click", () => {
    const statusSpan = container.querySelector("#auto-refresh-status");

    if (autoRefreshInterval) {
      clearInterval(autoRefreshInterval);
      autoRefreshInterval = null;
      statusSpan.textContent = "自動更新: OFF";
    } else {
      autoRefreshInterval = setInterval(async () => {
        const rows = await window.aivicApi.list(13);
        if (rows) renderRows(rows);
      }, 30000); // 30秒間隔
      statusSpan.textContent = "自動更新: ON";
    }
  });

  // アラート通知設定
  container.querySelector("#btn-alert-settings").addEventListener("click", () => {
    container.querySelector("#alert-settings-modal").classList.remove('hidden');
  });

  // モーダル関連イベント
  container.querySelector("#modal-close").addEventListener("click", () => {
    container.querySelector("#log-detail-modal").classList.add('hidden');
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#log-detail-modal").classList.add('hidden');
  });

  container.querySelector("#alert-modal-close").addEventListener("click", () => {
    container.querySelector("#alert-settings-modal").classList.add('hidden');
  });

  container.querySelector("#btn-cancel-alert-settings").addEventListener("click", () => {
    container.querySelector("#alert-settings-modal").classList.add('hidden');
  });

  container.querySelector("#btn-save-alert-settings").addEventListener("click", () => {
    alert("アラート通知設定を保存しました");
    container.querySelector("#alert-settings-modal").classList.add('hidden');
  });

  // 行レベル操作（イベントデリゲーション）
  container.addEventListener("click", async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const logId = detailBtn.dataset.id;
      const rows = await window.aivicApi.list(13);
      if (!rows) return;

      const log = rows.find(r => r.id === logId);
      if (!log) return;

      // 詳細モーダルに情報設定
      container.querySelector("#detail-log-id").textContent = log.id || '-';
      container.querySelector("#detail-data-type").textContent = log.データ種別 || '-';
      container.querySelector("#detail-data-source").textContent = log.データソース || '-';
      container.querySelector("#detail-start-time").textContent = formatDateTime(log.収集開始日時);
      container.querySelector("#detail-end-time").textContent = formatDateTime(log.収集終了日時);
      container.querySelector("#detail-status").textContent = log.処理ステータス || '-';
      container.querySelector("#detail-success-count").textContent = log.収集件数 || 0;
      container.querySelector("#detail-error-count").textContent = log.エラー件数 || 0;
      container.querySelector("#detail-processing-time").textContent = log.処理時間秒 ? `${log.処理時間秒}秒` : '-';
      container.querySelector("#detail-quality-score").textContent = log.データ品質スコア || '-';
      container.querySelector("#detail-error-message").textContent = log.エラーメッセージ || '-';
      container.querySelector("#detail-remarks").textContent = log.備考 || '-';

      currentLogId = logId;
      container.querySelector("#log-detail-modal").classList.remove('hidden');
    }

    // 単一再実行
    const retryBtn = e.target.closest(".retry-btn");
    if (retryBtn) {
      const logId = retryBtn.dataset.id;
      if (!confirm("このログを再実行しますか？")) return;

      try {
        const updated = await window.aivicApi.update(13, logId, {
          処理ステータス: '実行中',
          再実行フラグ: true,
          更新日時: new Date().toISOString()
        });

        if (updated) {
          alert("ログの再実行を開始しました");
          const rows = await window.aivicApi.list(13);
          if (rows) renderRows(rows);
        } else {
          alert("エラーログ再実行が失敗しました");
        }
      } catch (error) {
        alert("エラーログ再実行が失敗しました");
        console.error('再実行エラー:', error);
      }
    }
  });

  // 単一ログ再実行（モーダル内）
  container.querySelector("#btn-retry-single").addEventListener("click", async () => {
    if (!currentLogId) return;
    if (!confirm("このログを再実行しますか？")) return;

    try {
      const updated = await window.aivicApi.update(13, currentLogId, {
        処理ステータス: '実行中',
        再実行フラグ: true,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        alert("ログの再実行を開始しました");
        container.querySelector("#log-detail-modal").classList.add('hidden');
        const rows = await window.aivicApi.list(13);
        if (rows) renderRows(rows);
      } else {
        alert("エラーログ再実行が失敗しました");
      }
    } catch (error) {
      alert("エラーログ再実行が失敗しました");
      console.error('再実行エラー:', error);
    }
  });

  // モーダル外クリックで閉じる
  container.addEventListener("click", (e) => {
    if (e.target.classList.contains('modal')) {
      e.target.classList.add('hidden');
    }
  });
}
